对于下面动态规划方法实现的函数，以下选项中最适合表达其状态转移函数的为（ ）。

```cpp
int s[MAX_N], f[MAX_N][MAX_N];
int stone_merge(int n, int a[]) {
    for (int i = 1; i <= n; i++)
        s[i] = s[i - 1] + a[i];
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            if (i == j)
                f[i][j] = 0;
            else
                f[i][j] = MAX_F;
    for (int l = 1; l < n; l++)
        for (int i = 1; i <= n - l; i++) {
            int j = i + l;
            for (int k = i; k < j; k++)
                f[i][j] = min(f[i][j], f[i][k] + f[k + 1][j] + s[j] - s[i - 1]);
        }
    return f[1][n];
}
```

下面代码可以用来求最长上升子序列（LIS）的长度，如果输入是：5 1 7 3 5 9，则输出是（ ）。

```cpp
int a[2023], f[2023];
int main()
{
    int n,i,j,ans = -1;

    cin>>n;
    for( i=1; i<=n; i++){
        cin >> a[i];
        f[i] = 1;
    }

    for( i=1; i<=n; i++)
        for( j=1; j<i; j++)
            if(a[j] < a[i])
                f[i] = max(f[i], f[j]+1);
    for( i=1; i<=n; i++){
        ans = max(ans, f[i]);
        cout << f[i] << " ";
    }

    cout << ans << endl;
    return 0;
}
```

哈希表长31，按照下面的程序依次输入 4 17 28 30 4，则最后的 4 存入哪个位置？（ ）

```cpp
#include <iostream>
#include <string>
#include <cmath>
#include <vector>
using namespace std;

const int N=31;
int htab[N],flag[N];
int main()
{
    int n,x,i,j,k;

    cin >> n;
    for(i=0; i<n; i++){
        cin >> x;
        k=x%13;
        while(flag[k]) k = (k+1)%13;
        htab[k]=x;
        flag[k]=1;
    }

    for(i=0; i<N; i++)
        cout << htab[i] << " ";

    cout << endl;
    return 0;
}
```

